408]},{id="questgear",x=S[384]},{id=S[364],x=S[502]}},asideNote=S[73],talentString="245203220352013510050203001",ranks={{tree="Affliction",name=S[481],r=2,max=2},{tree="Affliction",name="Suppression",r=4,max=5},{tree="Affliction",name=S[553],r=5,max=5},{tree="Affliction",name="Grim Reach",r=2,max=2},{tree="Affliction",name=S[601],r=3,max=3},{tree="Affliction",name=S[521],r=2,max=2},{tree="Affliction",name=S[589],r=2,max=3},{tree="Affliction",name="Pandemic",r=3,max=3},{tree="Affliction",name="Malevolence",r=5,max=5},{tree="Affliction",name="Nightfall",r=2,max=2},{tree="Affliction",name="Siphon Life",r=1,max=1},{tree="Affliction",name="Soul Siphon",r=3,max=3},{tree="Affliction",name=S[609],r=5,max=5},{tree="Affliction",name="Wrack",r=1,max=1},{tree="Demonology",name=S[433],r=5,max=5},{tree="Demonology",name=S[477],r=2,max=2},{tree="Demonology",name=S[385],r=3,max=3},{tree="Demonology",name=S[286],r=1,max=1}},order={{l1=10,l2=13,tree="Affliction",name="Suppression",r1=1,r2=4,max=5},{l1=14,l2=18,tree="Affliction",name=S[553],r1=1,r2=5,max=5},{l1=19,l2=19,tree="Affliction",name="Grim Reach",r1=1,r2=1,max=2},{l1=20,l2=21,tree="Affliction",name=S[521],r1=1,r2=2,max=2},{l1=22,l2=24,tree="Affliction",name="Pandemic",r1=1,r2=3,max=3},{l1=25,l2=26,tree="Affliction",name="Nightfall",r1=1,r2=2,max=2},{l1=27,l2=29,tree="Affliction",name="Malevolence",r1=1,r2=3,max=5},{l1=30,l2=30,tree="Affliction",name="Siphon Life",r1=1,r2=1,max=1},{l1=31,l2=35,tree="Demonology",name=S[433],r1=1,r2=5,max=5},{l1=36,l2=37,tree="Demonology",name=S[477],r1=1,r2=2,max=2},{l1=38,l2=40,tree="Demonology",name=S[385],r1=1,r2=3,max=3},{l1=41,l2=41,tree="Demonology",name=S[286],r1=1,r2=1,max=1},{l1=42,l2=43,tree="Affliction",name="Malevolence",r1=4,r2=5,max=5},{l1=44,l2=44,tree="Affliction",name="Grim Reach",r1=2,r2=2,max=2},{l1=45,l2=45,tree="Affliction",name=S[481],r1=1,r2=1,max=2},{l1=46,l2=50,tree="Affliction",name=S[609],r1=1,r2=5,max=5},{l1=51,l2=51,tree="Affliction",name="Wrack",r1=1,r2=1,max=1},{l1=52,l2=52,tree="Affliction",name=S[481],r1=2,r2=2,max=2},{l1=53,l2=55,tree="Affliction",name="Soul Siphon",r1=1,r2=3,max=3},{l1=56,l2=58,tree="Affliction",name=S[601],r1=1,r2=3,max=3},{l1=59,l2=60,tree="Affliction",name=S[589],r1=1,r2=2,max=3}},blocks={{t="anchor",id="overview"},{t="p",s="eyebrow",x=S[386]},{t="p",s="legend",x="|cff71d5ffBlue text was updated for the WoW Forever hotfixes up to 10 November and is awaiting final review.|r"},{t="h1",x="Affliction",sub=S[443]},{t="p",s="lede",x="A simple damage-over-time and Shadow Bolt playstyle with a strong TBC feel: keep Corruption, Bane of Agony and your Curse ticking, fill with Shadow Bolt and drains, and let a Succubus add steady damage."},{t="pills",list={S[391],S[423]}},{t="anchor",id="journey"},{t="kicker",x=S[546]},{t="h2",x=S[329]},{t="p",x="These stages describe a practical route toward your chosen level-60 endpoint. Train new ranks, keep a few Soul Shards, and use the leveling point order below if you want an exact sequence."},{t="p",s="level",x="1–19 · Dots, drains and a demon"},{t="p",x="Open with Corruption and Bane of Agony, send your Imp or Voidwalker in, and finish with Shadow Bolt or your wand. Suppression (10–13) adds spell hit first, and Improved Corruption makes Corruption instant by level 18. Use Drain Life to recover the health you spend on Life Tap, and Drain Soul on dying enemies to collect Soul Shards."},{t="p",s="level",x="20–39 · Build the Affliction engine"},{t="p",x="Summon the Succubus at 20 for damage, or keep the Voidwalker for hard pulls. Improved Bane of Agony (20–21), Pandemic (22–24) and Nightfall (25–26) come first: Nightfall procs give you instant Shadow Bolts, and Pandemic doubles the critical damage bonus of your dots and drains. Malevolence and Siphon Life (30) follow, then Demonic Embrace, Demonic Aegis and Fel Vitality (31–40) make you and your demon much tougher."},{t="p",s="level",x="40–60 · Shadow Mastery and the demon package"},{t="p",x="Demonic Sacrifice at 41 lets you trade a demon you do not need for a lasting bonus. Malevolence reaches 5/5 at 43, Shadow Mastery 5/5 by 50 boosts every Shadow spell you cast, and Wrack at 51 adds a strong channel |cff71d5ffthat makes your Siphon Life, Corruption and Bane of Agony tick twice as fast.|r Improved Life Tap, Soul Siphon, Improved Drains and Fel Concentration finish the build at 60."},{t="anchor",id="talents"},{t="kicker",x=S[367]},{t="h2",x=S[391]},{t="p",x=S[47]},{t="widget",w="talents"},{t="h4",s="summary",x=S[394]},{t="widget",w="ranks"},{t="h4",s="summary",x=S[351]},{t="p",x=S[70]},{t="widget",w="order"},{t="p",s="notice",x="Wrack is the Affliction capstone and needs Siphon Life; it |cff71d5ffchannels for 6 seconds, dealing Shadow damage every second while your Siphon Life, Corruption and Bane of Agony tick twice as fast,|r so this build takes both. Soul Siphon also boosts Wrack for each |cff71d5ffCorruption, Siphon Life and Bane of Agony|r on the target. Only 4/5 Suppression is taken, so this build gets 4% spell hit from talents."},{t="anchor",id="stats"},{t="kicker",x=S[457]},{t="h2",x=S[375]},{t="p",x="Affliction wants hit until the cap, then spell power and critical strike. In Forever damage-over-time ticks can crit, so crit is worth much more than in Classic."},{t="h3",x=S[528]},{t="stat",i=1,b=S[571],x=S[494]},{t="stat",i=2,b="Stamina",x=S[323]},{t="stat",i=3,b="Spirit",x="more health and mana from Life Tap"},{t="stat",i=4,b="Intellect",x="mana pool"},{t="p",s="small",x="Wands with Shadow damage and Spirit are good leveling picks for Affliction."},{t="h3",x="At level 60"},{t="stat",i=1,b="Hit chance",x="to 17%"},{t="stat",i=2,b="Spell power",x=S[494]},{t="stat",i=3,b=S[503],x=""},{t="stat",i=4,b="Haste",x=""},{t="stat",i=5,b="Intellect",x=""},{t="p",s="small",x="Four points in Suppression give 4% hit, so you need 13% from gear. Past the cap, hit does nothing; swap it for spell power or crit."},{t="p",s="notice",x=S[48]},{t="anchor",id="combat"},{t="kicker",x=S[376]},{t="h2",x=S[409]},{t="p",x="Treat this as a priority guide, not a fixed loop. While leveling, omit talents and spells you have not learned. Target lifespan, mana and pull size decide how many effects are worth applying."},{t="h4",x="Set up the target"},{t="p",x="Send your Succubus in first. Apply your Curse (Curse of the Elements for dungeon bosses), then Bane of Agony and Corruption. In Forever a Bane and a Curse of yours can sit on the same enemy, so you never choose between damage and utility. Skip Bane of Agony on enemies that will die before it pays off."},{t="h4",x="Fill with Shadow Bolt"},{t="p",x="Shadow Bolt is your main filler. Shadow Mastery, Malevolence and Shadow damage gear all improve it. Corruption and your drains can trigger Nightfall; when Shadow Trance appears, your next Shadow Bolt is instant, so spend it straight away."},{t="h4",x="Drain when your effects are up"},{t="p",x="Soul Siphon adds 12% to Drain Life, Drain Soul and Wrack for each |cff71d5ffCorruption, Siphon Life and Bane of Agony|r on the target (up to 36%), and Improved Drains adds another 20% to your drains. From 51, channel Wrack while your dots tick: |cff71d5ffit lasts 6 seconds and makes Siphon Life, Corruption and Bane of Agony tick twice as fast, without changing how long they last.|r With two or three effects up, Drain Life is both a damage and a healing button. Fel Concentration keeps the channel going while you are hit."},{t="h4",x="Execute with Drain Soul"},{t="p",x="Below 20% health, the Improved Drains bonus on Drain Soul is tripled. Switch from Shadow Bolt to Drain Soul for the last part of a fight; it also refills your Soul Shards when the enemy dies."},{t="h4",x="Manage mana with Life Tap"},{t="p",x="Life Tap now scales with Spirit, not spell damage. Tap while your health is comfortable, then let Drain Life recover it. Demonic Energies also gives your demon the mana you gain. Do not tap yourself into danger just to fill the mana bar."},{t="h4",x="Handle packs and danger"},{t="p",x="Spread Corruption and Bane of Agony with mouseover macros on packs that will live long enough. Keep Fear, Death Coil and Seduction ready. Spell Lock from a Felhunter is the better choice against heavy casters."},{t="abil",names={"Corruption",S[616],S[424],"Shadow Bolt","Drain Life","Drain Soul","Life Tap","Summon Succubus"}},{t="h3",x=S[482]},{t="p",x="Shadow spell damage and general spell power come first: almost everything you cast is Shadow. Intellect adds mana and critical chance, which Pandemic rewards on dots and drains. Spirit improves Life Tap; Stamina gives you health to tap and survive. This build has 4% hit from Suppression, so hit on gear is still useful against bosses. Fire-only gear does nothing for this build and is hidden in the atlas."},{t="p",x=S[54]},{t="h3",x=S[319]},{t="p",x="Carry Soul Shards for Healthstones, a Soulstone and summons, and a stack of water: Warlocks cannot conjure drinks. Create Spellstone (from 36) is a weapon imbue that adds Shadow damage and spell haste, which suits this build better than a Firestone."},{t="p",x="Your Succubus is the default damage pet; with Demonic Sacrifice you can instead sacrifice the Imp for 15% more Shadow damage when you do not need a demon out. Swap to the Felhunter for caster-heavy dungeons, and to the Voidwalker for risky solo pulls. Bring Curse of the Elements unless another Warlock already covers it."},{t="anchor",id="macros"},{t="kicker",x=S[444]},{t="h2",x=S[304]},{t="p",x=S[46]},{t="p",s="notice",x=S[38]},{t="macro",n=S[395],x=S[62],code=S[141]},{t="macro",n=S[434],x=S[124],code=S[154]},{t="macro",n=S[334],x=S[65],code=S[113]},{t="macro",n=S[373],x=S[77],code=S[132]},{t="macro",n=S[529],x=S[97],code=S[181]},{t="macro",n=S[495],x=S[114],code=S[172]},{t="macro",n=S[377],x=S[112],code=S[120]},{t="macro",n=S[445],x=S[106],code=S[157]},{t="macro",n=S[435],x=S[100],code=S[155]},{t="macro",n=S[368],x=S[101],code=S[189]},{t="macro",n=S[504],x=S[144],code=S[246]},{t="macro",n=S[410],x=S[102],code=S[216]},{t="macro",n=S[572],x=S[201],code=S[335]},{t="macro",n="Drain Soul execute",x="Channel Drain Soul on the hovered enemy or your target when it drops below 20%. Releasing the key does not cancel the channel.",code="#showtooltip Drain Soul\n/cast [@mouseover,harm,nodead][harm,nodead] Drain Soul"},{t="macro",n="Shadow Bolt / Shift Drain Life",x="Normal press casts Shadow Bolt at your target. Hold Shift to start Drain Life instead when you need health back.",code="#showtooltip\n/cast [mod:shift,harm,nodead] Drain Life; [harm,nodead] Shadow Bolt"},{t="p",s="small",x=S[195]},{t="anchor",id="dungeons"},{t="kicker",x=S[505]},{t="h2",x=S[352]},{t="p",x=S[51]},{t="widget",w="rarity"},{t="p",s="notice",x=S[36]},{t="p",s="notice",x=S[44]},{t="widget",w="loot"},{t="anchor",id="professions"},{t="kicker",x=S[378]},{t="h2",x=S[349]},{t="p",x=S[53]},{t="widget",w="prof"},{t="anchor",id="crafting"},{t="kicker",x=S[396]},{t="h2",x=S[330]},{t="p",x=S[28]},{t="widget",w="craft"},{t="anchor",id="questgear"},{t="kicker",x=S[379]},{t="h2",x=S[301]},{t="p",x=S[35]},{t="widget",w="quest"},{t="anchor",id=S[364]},{t="kicker",x=S[506]},{t="h2",x="Your notes"},{t="widget",w="notes"},{t="p",s="small",x=S[60]}}},{id="demonology",name="Demonology",token="DEMO",gearBrackets={{b="Quest rewards",no="Quest rewards that fit this spec's stat priority, sorted by quest level. The tooltip names the quest, its level, the quest giver and the faction. Quest level is not the minimum pickup level.",keys={"st-warlock-1","st-warlock-2","warlock-g39","warlock-g98","warlock-g137","warlock-g52","warlock-g67","warlock-g121","warlock-g97","warlock-g4","warlock-g38","warlock-g95","warlock-g96","warlock-g23","warlock-g24","warlock-g73","warlock-g83","warlock-g140","warlock-g136","warlock-g18","warlock-g27","warlock-g55","warlock-g76","warlock-g114","warlock-g118","warlock-g58","warlock-g89","warlock-g43","warlock-g59","warlock-g70","warlock-g113","warlock-g119","warlock-g21","warlock-g107","warlock-g13","warlock-g